export async function renameCategory(store: Store, oldName: string, newName: string): Promise<string | null> {
  // Remember the store for later isCategoryInUse calls without explicit store
  lastUsedStore = store;

  // Validate the new category name
  if (!isValidName(newName)) return 'Category must be 1\u201140 characters and not contain < or >.';

  const data = await loadData(store);
  const allNames = [...DEFAULT_CATEGORIES, ...data.custom];
  // Conflict if another category (case-insensitive) already has the new name
  const conflict = allNames.some((n) => n.toLowerCase() === newName.toLowerCase());
  if (conflict) return 'Category already exists.';

  const oldLC = oldName.toLowerCase();
  const defaultMatch = DEFAULT_CATEGORIES.find((c) => c.toLowerCase() === oldLC);
  const customIdx = data.custom.findIndex((c) => c.toLowerCase() === oldLC);

  if (!defaultMatch && customIdx === -1) return 'Category not found.';

  // Update the categories list
  if (defaultMatch) {
    // Keep original default name as key in rename map
    data.rename[defaultMatch] = newName;
  } else {
    const oldCustom = data.custom[customIdx];
    data.custom[customIdx] = newName;
    // Preserve any rename mapping for the old custom name
    if (data.rename[oldCustom]) {
      data.rename[newName] = data.rename[oldCustom];
      delete data.rename[oldCustom];
    }
  }

  // Update receipts that reference the old category name (case-insensitive)
  const receipts = await getAllReceipts(store);
  for (const r of receipts) {
    if (r.category && r.category.toLowerCase() === oldLC) {
      const updated = { ...r, category: newName };
      await store.put('receipts', updated as any);
    }
  }

  await saveData(store, data);
  return null;
}"}

