  for (const def of DEFAULT_CATEGORIES) {
    const effective = data.rename[def] ?? def;
    effectiveNames.add(effective.toLowerCase());
  }
  for (const cust of data.custom) {
    effectiveNames.add(cust.toLowerCase());
